#!/usr/bin/env python3
"""
Round 193o (culprits-tiles-more), 13 October 2026.

- surveillance_watch.py (new): Surveillance Watch's public API, weekly.

Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/surveillance_watch.py': ''}

def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round193o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round193o_tiles: wrote {path}")
    if not changed:
        print("round193o_tiles: already applied")


if __name__ == "__main__":
    main()
